from shellthreatmodel.engines.pasta_engine import PASTAThreatEngine
from shellthreatmodel.models.architecture import ArchitectureModel, Component, DataFlow, TrustBoundary


def build_sample_architecture() -> ArchitectureModel:
    return ArchitectureModel(
        title="Order Processing Platform",
        components=[
            Component(name="Web Portal", type="api"),
            Component(name="Order Service", type="service"),
            Component(name="Inventory DB", type="database"),
        ],
        data_flows=[
            DataFlow(
                source="Web Portal",
                destination="Order Service",
                description="Checkout workflow",
                protocol="https",
                sensitive=True,
            ),
            DataFlow(
                source="Order Service",
                destination="Inventory DB",
                description="Inventory ETL job",
                protocol="internal",
                sensitive=True,
            ),
        ],
        trust_boundaries=[
            TrustBoundary(name="Public Zone", components=["Web Portal"]),
            TrustBoundary(name="Trusted Internal", components=["Order Service", "Inventory DB"]),
        ],
    )


def test_pasta_engine_produces_methodology_annotations():
    engine = PASTAThreatEngine()
    architecture = build_sample_architecture()

    threats = list(engine.generate(architecture))

    assert threats, "PASTA engine should produce threats for mixed trust zones"
    assert all(threat.methodology.startswith("PASTA Step ") for threat in threats)
    assert any("Weakness" in threat.methodology for threat in threats)
    assert all(1 <= threat.dread.damage <= 10 for threat in threats)
